const response = $input.first().json;
if (!response.success) {
  // topic_queue being empty is not a failure -- it just means no topics
  // have been approved from the dashboard yet. Log and stop quietly rather
  // than throwing, so an empty queue doesn't page anyone.
  return [{ json: { status: 'skipped', message: response.message ?? 'No queued topic to generate' } }];
}
return [{ json: { status: 'queued', queue_id: response.queue_id, message: 'DSX-CA1 running in background — article will appear in HITL queue when ready' } }];
